# Spec for JSW_R2_workbook_v7. Typed numbers only in INPUTS. Sheets hold formulas over in_<id> names.
# status: verified | assumption | scenario | derived | not_found. Figures with status assumption carry a range.

README = [
 "JSW Ventures R2 workbook v7. Built 5 Oct 2026 by script (build/build_workbook.py from build/spec_v7.py).",
 "Flow: Inputs (every figure with source, URL, date, claim type, confidence, status) -> WE_ sheets (one worked revenue and cost example per sub-sector, formulas only) -> EX_ sheets (exhibit data, formulas only) -> Check (typed numbers outside Inputs must be 0).",
 "Colour code: blue = typed input (Inputs sheet only). Black = formula. Amber fill = assumption with a range. Red fill = not found, left blank.",
 "Tags: verified = primary or reputable secondary source opened and figure matched; assumption = no source, range stated; scenario = an illustrative size chosen for the worked example (a Rs 10,000 payment, a Rs 20,000 policy), not a market fact; derived = computed by formula.",
 "Terms: MDR = merchant discount rate, the fee deducted from what a merchant receives. P2M = person to merchant. Yield = interest and fees earned as a share of loans. Cost of funds = interest paid on borrowings as a share of borrowings. Credit cost = loan losses and provisions as a share of loans. Opex to AUM = operating cost as a share of loans. ROA = profit as a share of assets. Persistency = share of policies renewed. Trail = recurring commission on assets. NRR = net revenue retention, revenue from last year's customers this year over last year.",
]

def I(id, metric, figure, unit, period, source, url, date, claim, conf, status, lo=None, hi=None, note=""):
    return dict(id=id, metric=metric, figure=figure, unit=unit, period=period, source=source, url=url,
                source_date=date, claim_type=claim, confidence=conf, status=status, range_low=lo, range_high=hi, note=note)

